// Üretilen dosya: tool/ozgun/uret.py. Doğa · Bitkiler ve ormanlar; Türkiye'nin endemik türleri (zor).
const ozNature2Zor = <(String, String, List<String>, String)>[
  ('Bitişik bitki hücrelerinin hücre duvarlarını delip geçerek sitoplazmaları arasında doğrudan madde alışverişi sağlayan kanallara ne ad verilir?', 'Plazmodesma', ['Desmozom', 'Stoma', 'Hücreler arası lentisel boşluğu'], 'Plazmodesmalar komşu bitki hücrelerinin sitoplazmalarını birbirine bağlayan ince kanallardır; hayvan hücrelerindeki boşluklu bağlantılara benzer işlev görür.'),
  ('Fotosentezde açığa çıkan oksijen atomlarının hangi molekülden geldiği izotop deneyleriyle gösterilmiştir?', 'Sudan', ['Karbondioksitten', 'Glikozdan', 'Klorofilden'], 'Ağır oksijen izotopuyla işaretlenmiş su kullanıldığında açığa çıkan oksijenin de işaretli olduğu görülmüş; böylece oksijenin suyun parçalanmasından geldiği anlaşılmıştır.'),
  ('Calvin döngüsünde karbondioksiti ilk organik moleküle bağlayan ve yeryüzünde en bol bulunan protein olduğu düşünülen enzim hangisidir?', 'RuBisCO', ['ATP sentaz', 'Amilaz', 'Katalaz'], 'Ribuloz bisfosfat karboksilaz/oksijenaz (RuBisCO) CO2\'yi RuBP\'ye bağlar; bitkilerde çok miktarda bulunduğu için en bol protein olarak anılır.'),
  ('Jan Ingenhousz 18. yüzyılda bitkilerin havayı \'temizleme\' yeteneğiyle ilgili hangi önemli koşulu ortaya koymuştur?', 'Bu etkinin yalnızca ışıkta ve yeşil kısımlarda olması', ['Bitkilerin topraktan oksijen emmesi', 'Etkinin yalnızca kök hücrelerinde görülmesi', 'Etkinin sıcaklıktan ve ışıktan tamamen bağımsız olması'], 'Ingenhousz, bitkilerin oksijen üretiminin ışık gerektirdiğini ve yeşil dokularda gerçekleştiğini, karanlıkta ise bitkilerin de havayı tükettiğini göstermiştir.'),
  ('Sıcaklığın uygun tutulduğu bir serada fotosentez hızı belirli bir noktadan sonra ışık artırıldığı hâlde yükselmiyor. Bunun en olası nedeni nedir?', 'Başka bir etken, örneğin CO2 miktarı sınırlayıcı hâle gelmiştir', ['Klorofil ışıkla tamamen parçalanmıştır', 'Bitki fotosentez yerine kemosentez yapmaya başlamıştır', 'Stomalar ışık arttıkça yaprak yüzeyinden kalıcı olarak kaybolmuştur'], 'Sınırlayıcı etken ilkesine göre ışık yeterli düzeye ulaşınca hız, en az bulunan başka etkene, sıklıkla karbondioksit derişimine bağlı kalır.'),
  ('Kloroplastın kendine ait DNA\'sı ve ribozomlarının bulunması, bu organelin kökeni hakkında hangi kuramı destekler?', 'Endosimbiyoz kuramını', ['Kendiliğinden oluş kuramını', 'Kıtaların kayması kuramını', 'Kullanma-kullanmama kuramını'], 'Endosimbiyoz kuramına göre kloroplastlar, bir ata hücre tarafından yutulmuş fotosentetik bakterilerden, siyanobakterilerden türemiştir.'),
  ('Uzun bir ağaçta suyun köklerden yapraklara taşınmasını en çok açıklayan kuram, su moleküllerinin hangi özelliğine dayanır?', 'Moleküllerin birbirine tutunması ve terlemenin çekmesi', ['Floem hücrelerinin kasılması', 'Kökteki kalp benzeri bir pompanın itmesi', 'Suyun yerçekimine karşı kendiliğinden yukarıya buharlaşması'], 'Kohezyon-gerilim kuramına göre yapraklardaki terleme bir çekim oluşturur; birbirine tutunan su molekülleri ksilemde kesintisiz bir sütun hâlinde yukarı çekilir.'),
  ('Bir ağacın gövdesinden kabuk ve hemen altındaki doku bir halka şeklinde tamamen soyulursa ağaç bir süre sonra kurur. Bunun temel nedeni nedir?', 'Floem kesildiği için köklere besin ulaşmaz', ['Ksilem kesildiği için yapraklara su gitmez', 'Yapraklar fotosentez yapamaz hâle gelir', 'Kambiyum fazla büyüyerek gövdenin içini tıkar'], 'Halka soyma ile kabuktaki floem kesilir; ksilem sağlam kaldığı için yapraklar bir süre su alır, ama kökler şeker alamayıp ölünce bütün ağaç kurur.'),
  ('Çimenler biçildikten sonra kısa sürede yeniden uzar; oysa uçları kesilen birçok bitki aynı biçimde uzamaz. Çimenlerdeki bu yeteneği en iyi açıklayan nedir?', 'Boğum aralarının tabanında ara meristem bulunması', ['Yapraklarda kambiyum bulunması', 'Köklerinin fotosentez yapması', 'Uç meristemlerinin daima toprak altında saklı olması'], 'Buğdaygillerde ara (interkalar) meristemler boğumların ve yaprak kınlarının tabanında yer alır; üst kısım kesilse de buradan büyüme sürer.'),
  ('Genç gövdelerde ve yaprak saplarında köşelerde kalınlaşmış, canlı ve esnek hücrelerden oluşan destek dokusu hangisidir?', 'Kollenkima', ['Sklerenkima', 'Parankima', 'Floem'], 'Kollenkima canlı hücrelerden oluşur ve duvarları köşelerde kalınlaşmıştır; büyüyen organlara esneklikle birlikte destek sağlar. Kereviz saplarının lifleri buna örnektir.'),
  ('Armudun etli kısmında dişlerin altında hissedilen sert, kumlu tanecikler hangi hücre tipinden oluşur?', 'Taş hücreleri', ['Kök tüyü hücreleri', 'Arkadaş hücreleri', 'Kristal içeren bekçi hücreleri'], 'Armuttaki kumlu doku, sklerenkimanın bir türü olan sklereitlerden, yani duvarları çok kalınlaşmış taş hücrelerinden oluşur.'),
  ('Endodermis hücrelerinin duvarlarında bulunan ve suyun hücreler arasından serbestçe geçmesini engelleyerek kökte seçici geçişi sağlayan şerit hangisidir?', 'Kaspari şeridi', ['Orta lamel', 'Kütikula', 'Kalburlu levha ve plazmodesma'], 'Kaspari şeridi süberin içeren mumsu bir banttır; su ve mineraller endodermisi geçerken hücre zarından geçmek zorunda kalır, böylece alım denetlenir.'),
  ('Asmanın bir desteğe sarılarak tırmanmasını sağlayan sülükleri gövde kökenlidir. Bezelyede ise sülükler hangi organın değişikliğe uğramasıyla oluşur?', 'Yaprakçıkların', ['Köklerin', 'Çiçek saplarının', 'Tohum kabuğunun'], 'Bezelyede bileşik yaprağın uçtaki yaprakçıkları sülüğe dönüşmüştür; asmada ise sülükler değişmiş sürgünlerdir.'),
  ('Kırmızı, boru biçimli, kokusuz ve bol nektarlı çiçekler Amerika kıtasında en çok hangi hayvanlarca tozlaştırılır?', 'Sinek kuşları', ['Yarasalar', 'Gece kelebekleri', 'Arılar'], 'Kuşlar kırmızıyı iyi görür ama koku duyuları zayıftır; uzun gagaları boru biçimli çiçeklerdeki nektara ulaşmaya uygundur.'),
  ('Bazı orkideler çiçek biçimi ve kokusuyla dişi arıları taklit eder; erkek arı çiftleşmeye çalışırken polenleri taşır. Bu stratejinin adı nedir?', 'Cinsel aldatma', ['Kendi kendine tozlaşma', 'Rüzgârla tozlaşma', 'Su ile tozlaşma'], 'Ophrys gibi orkidelerde görülen bu yöntemde çiçek ödül vermez; erkek böcek dişi sanıp çiçeği ziyaret eder ve polen taşır.'),
  ('Kiraz, şeftali ve zeytinde meyvenin iç kısmındaki sert çekirdek, meyve kabuğunun hangi katmanının odunlaşmasıyla oluşur?', 'İç meyve kabuğunun (endokarp)', ['Tohum kabuğunun', 'Dış meyve kabuğunun (ekzokarp)', 'Çiçek tablasının dış yüzeyinin'], 'Sert çekirdekli meyvelerde (drup) endokarp taşlaşarak tohumu saran sert çekirdeği oluşturur; tohum bunun içindedir.'),
  ('Çileğin yüzeyinde \'tohum\' sandığımız küçük sarı tanecikler botanik açıdan nedir?', 'Her biri birer küçük kuru meyvedir', ['Çileğin polen keseleridir', 'Kurumuş taç yapraklarıdır', 'Yaprakların küçülmüş kalıntılarıdır'], 'Çileğin etli kısmı şişmiş çiçek tablasıdır; üzerindeki tanecikler içinde tek tohum bulunan küçük kuru meyvelerdir (aken).'),
  ('Kültür muzlarının tohumsuz olmasının nedeni nedir?', 'Meyvenin döllenme olmadan gelişmesi', ['Tohumların meyve olgunlaşınca erimesi', 'Muz bitkisinin hiç çiçek açmaması', 'Tohumların kabukta saklanması'], 'Döllenmesiz meyve oluşumuna partenokarpi denir; kültür muzları üç takımlı kısır bitkiler olduğundan tohumsuz meyve verir ve sürgünle çoğaltılır.'),
  ('Bazı bitkilerin tohumları kuşların sindirim kanalından geçmeden çok zor çimlenir. Bunun en akla yatkın açıklaması nedir?', 'Sindirim asitleri sert tohum kabuğunu inceltir', ['Kuşlar tohumlara azot ekler', 'Tohumlar kuşun vücut ısısıyla olgunlaşır', 'Sindirim kanalı tohumlara çimlenme için gerekli ışığı verir'], 'Sert tohum kabuğu suyun girmesini engeller; sindirim sırasında aşınması kabuğu geçirgen hâle getirerek çimlenmeyi kolaylaştırır.'),
  ('Fasulyede çimlenme sırasında çenekler toprak üstüne çıkar; bezelyede ise toprak altında kalır. Bezelyedeki çimlenme tipine ne ad verilir?', 'Toprak altı (hipogeal) çimlenme', ['Toprak üstü (epigeal) çimlenme', 'Vivipari', 'Ana bitki üzerinde kendiliğinden çimlenme'], 'Hipogeal çimlenmede çenekler toprakta kalır ve yalnızca sürgün yüzeye çıkar; epigeal çimlenmede çenekler toprak yüzüne taşınır.'),
  ('Bitki doku kültüründe besi ortamındaki oksin oranı sitokinine göre yüksek tutulursa kallus dokusundan daha çok hangi organın gelişmesi beklenir?', 'Kök', ['Sürgün', 'Çiçek', 'Meyve'], 'Doku kültüründe yüksek oksin/sitokinin oranı kök oluşumunu, düşük oran ise sürgün oluşumunu teşvik eder.'),
  ('Polen tüpünün tepecikten yumurtalığa doğru, tohum taslağının salgıladığı maddelere yönelerek büyümesi hangi harekete örnektir?', 'Kemotropizma', ['Gravitropizma', 'Sismonasti', 'Niktinasti'], 'Kimyasal maddelere yönelimli büyüme kemotropizmadır; polen tüpü dişi gametofitin salgıladığı sinyallerle yönlendirilir.'),
  ('Charles Darwin ve oğlu Francis, kanarya otu fideleriyle yaptıkları deneylerde ışığa eğilmenin fidenin hangi bölümü örtüldüğünde gerçekleşmediğini göstermiştir?', 'Koleoptilin ucu', ['Kök ucu', 'Koleoptilin tabanı', 'Tohum kabuğu'], 'Uç kısmı opak bir başlıkla örtülen fideler ışığa eğilmedi; bu, ışığın uçta algılandığını ve bir sinyalin aşağı iletildiğini gösterdi. Sinyal daha sonra oksin olarak tanımlandı.'),
  ('Krizantem gibi kısa gün bitkilerinin çiçeklenmesini belirleyen asıl etken aşağıdakilerden hangisidir?', 'Kesintisiz karanlık dönemin uzunluğu', ['Gündüz sıcaklığının yüksekliği', 'Toprağın tuzluluk oranı', 'Bitkinin taşıdığı yaprakların toplam sayısı'], 'Deneyler kısa gün bitkilerinin aslında uzun gece bitkileri olduğunu göstermiştir; uzun karanlık dönem kısa bir ışıkla bölünürse çiçeklenme gerçekleşmez.'),
  ('Seracılar kasım ayında satılmak üzere yetiştirdikleri kısa gün bitkilerini yaz aylarında çiçeklendirmek isterse hangi yöntemi uygulayabilir?', 'Bitkileri her akşam karartma örtüsüyle örtmek', ['Gece boyunca serayı aydınlatmak', 'Bitkileri daha sık sulamak', 'Seraya gündüz saatlerinde ek karbondioksit vermek'], 'Kısa gün bitkileri uzun ve kesintisiz karanlığa ihtiyaç duyar; yazın erken karartma ile gece uzatılarak çiçeklenme sağlanır.'),
  ('Bitkilerin gün uzunluğunu algılamasında görev alan ve kırmızı ile uzak kırmızı ışığa duyarlı pigment hangisidir?', 'Fitokrom', ['Klorofil b', 'Antosiyanin', 'Karoten'], 'Fitokrom kırmızı ve uzak kırmızı ışıkla iki biçim arasında dönüşür; bitki bu dönüşüm sayesinde gece uzunluğunu ölçer.'),
  ('Bir tarlada ekilen bitkilerin özellikle yaşlı alt yapraklarının sararıp büyümenin yavaşladığı görülüyor. Bu belirtiler en çok hangi elementin eksikliğini düşündürür?', 'Azot', ['Kükürt', 'Bor', 'Klor'], 'Azot bitki içinde hareketlidir; eksik olduğunda yaşlı yapraklardaki azot genç yapraklara taşınır ve önce alt yapraklar sararır.'),
  ('Bitki köklerinin çoğuyla ortak yaşayan ve kökün emici yüzeyini genişleterek özellikle fosfor alımını artıran canlılar hangileridir?', 'Mikorizal mantarlar', ['Azot bağlayan siyanobakteriler', 'Toprak solucanları', 'Parazit nematodlar'], 'Mikoriza mantar ile kök arasındaki ortak yaşamdır; mantar ipliksileri toprağa yayılarak su ve mineralleri, özellikle fosforu bitkiye iletir.'),
  ('Pancarın koyu kırmızı-mor rengini veren ve antosiyaninlerden kimyasal olarak farklı olan pigment grubu hangisidir?', 'Betalainler', ['Klorofiller', 'Karotenler', 'Taninler ve flavonlar'], 'Pancar ve karanfilgillerin bazı üyelerinde renk, azot içeren betalain pigmentlerinden gelir; bu bitkilerde antosiyanin bulunmaz.'),
  ('Yaprak sapının dalla birleştiği yerde oluşan ve yaprağın kopmasını sağlayan özel hücre tabakasına ne ad verilir?', 'Ayrılma tabakası', ['Kaspari şeridi', 'Kambiyum halkası', 'Kütikula ve epidermis tabakası birlikte'], 'Sonbaharda yaprak sapının tabanında ayrılma tabakası oluşur; hücreler arasındaki bağlar zayıflar ve yaprak düşer. Etilen bu süreci hızlandırır.'),
  ('Turbalıkların oluşumunda başlıca rol oynayan ve kendi kuru ağırlığının çok katı su tutabilen yosun cinsi hangisidir?', 'Sphagnum (turba yosunu)', ['Marchantia (ciğer otu)', 'Equisetum (at kuyruğu)', 'Polypodium (benli eğrelti otu)'], 'Sphagnum\'un ölü hücreleri süngerimsi bir yapıyla çok su tutar; asidik ve oksijensiz bataklıklarda çürümeden birikerek turbayı oluşturur.'),
  ('Karayosunlarında yaşam döngüsünün baskın, yani gözümüzle gördüğümüz yeşil evresi hangisidir?', 'Gametofit', ['Sporofit', 'Zigot', 'Polen tüpü'], 'Yosunlarda yeşil, yaprakçıklı bitkicik haploit gametofittir; sporofit onun üzerinde gelişen ve ona bağımlı kalan sap ve kapsüldür.'),
  ('At kuyruğu bitkisinin gövdesi eskiden kap kacak ovmak için kullanılırdı. Bu kullanıma olanak veren özelliği nedir?', 'Dokularında silis birikmesi', ['Gövdesinin yağlı olması', 'Yapraklarının yapışkan olması', 'Köklerinin sabun içermesi'], 'Equisetum gövdesinde biriken silika onu pürüzlü yapar; bu nedenle kalay ve tencere parlatmak için kullanılmıştır.'),
  ('Kozalaklı ağaçlar arasında kışın iğne yapraklarını döken ve bu yönüyle ayrıksı olan cins hangisidir?', 'Melez (Larix)', ['Göknar (Abies)', 'Ladin (Picea)', 'Sedir (Cedrus)'], 'Melez ağaçları açık tohumlu ve kozalaklı oldukları hâlde sonbaharda yapraklarını sarartıp döker; diğer kozalaklıların çoğu herdem yeşildir.'),
  ('Çam ağacında dişi kozalağın tozlaşmadan tohumların olgunlaşmasına kadar geçen süre için aşağıdakilerden hangisi doğrudur?', 'Genellikle iki yıla yakın sürer', ['Birkaç gün içinde tamamlanır', 'Yaklaşık bir hafta sürer', 'Tozlaşmayla aynı gün içinde olgunlaşır'], 'Çamlarda polen tüpü yavaş gelişir; döllenme tozlaşmadan yaklaşık bir yıl sonra olur ve tohumlar çoğu türde ikinci yılın sonbaharında olgunlaşır.'),
  ('Palmiyelerin boyları çok uzasa da gövdelerinin kalınlığı yıllar içinde fazla değişmez. Bunun başlıca nedeni nedir?', 'Gerçek vasküler kambiyumları yoktur', ['Yapraklarını hiç dökmezler', 'Kökleri çok yüzeyseldir', 'Gövdelerinin içi tamamen boştur ve hava doludur'], 'Palmiyeler tek çeneklidir ve odunsu bitkilerdeki gibi yıllık halka üreten vasküler kambiyumdan yoksundur; bu yüzden kalınlaşma sınırlı kalır.'),
  ('Bitkilerin evriminde karaya geçişte ortaya çıkan özellikler sırasıyla düşünüldüğünde, aşağıdakilerden hangisi en son ortaya çıkan özelliktir?', 'Çiçek', ['İletim dokusu', 'Tohum', 'Kütikula'], 'Kütikula erken kara bitkilerinde, iletim dokusu eğreltilerde, tohum açık tohumlularda, çiçek ise en son kapalı tohumlularda ortaya çıkmıştır.'),
  ('Lahana, brokoli, karnabahar ve Brüksel lahanası botanik açıdan nasıl bir ilişkiye sahiptir?', 'Dördü de aynı türün kültür çeşitleridir', ['Her biri farklı bir familyadan gelir', 'Her biri ayrı ve birbirinden bağımsız yabani türdür', 'Tahıllarla yapılmış melezlerdir'], 'Bu sebzelerin tümü Brassica oleracea türünden seçilimle geliştirilmiştir; lahanada yaprak, brokolide çiçek durumu, Brüksel lahanasında yan tomurcuklar büyütülmüştür.'),
  ('Kimyon, anason ve kişniş gibi baharatların \'tohum\' olarak satılan kısımları botanik açıdan nedir?', 'Kuru meyvelerdir', ['Kurutulmuş çiçek tomurcuklarıdır', 'Kurutulmuş kök parçalarıdır', 'Polen kümeleridir'], 'Maydanozgillerin baharat olarak kullanılan tanecikleri, içinde tohum bulunan ve ikiye ayrılabilen kuru meyvelerdir (şizokarp).'),
  ('Haşhaş ve gelincik aynı familyanın üyeleridir. Bu bitkilerin tohumları hangi tip meyve içinde bulunur?', 'Tepesindeki deliklerden tohum saçan bir kapsül', ['Etli ve sulu bir üzümsü meyve', 'Kanatlı ve tek tohumlu bir meyve', 'Taşlaşmış iç kabuğu olan sert çekirdekli bir meyve'], 'Gelincikgillerde meyve bir kapsüldür; olgunlaşınca tepesindeki küçük deliklerden tohumlar tuzluk gibi saçılır.'),
  ('Erguvan ağacı (Cercis siliquastrum) hangi familyaya aittir ve bunu gösteren özelliği nedir?', 'Baklagillerdendir; meyvesi bakladır', ['Gülgillerdendir; meyvesi elmaya benzer', 'Zambakgillerdendir; soğanı vardır', 'Turpgillerdendir; çiçekleri haç biçimlidir'], 'Erguvan baklagiller familyasındandır; ilkbaharda açan pembe-mor çiçeklerinden sonra yassı baklalar oluşturur.'),
  ('Erguvan ağacının çiçekleri yalnızca genç dallarda değil, kalın dallarda ve hatta gövdede de açar. Bu özelliğe ne ad verilir?', 'Kaulifori', ['Partenokarpi', 'Vernalizasyon', 'Gutasyon ve kök basıncı'], 'Çiçeklerin gövde ve yaşlı dallar üzerinde doğrudan oluşmasına kaulifori denir; kakao ve erguvan bu özelliği gösterir.'),
  ('Papatyagiller familyasında en çok türü olan cinslerden biri olup Türkiye\'de pek çok endemik türü bulunan, peygamber çiçeği adıyla bilinen cins hangisidir?', 'Centaurea', ['Crocus', 'Tulipa', 'Quercus ve Fagus'], 'Centaurea papatyagillerdendir ve Türkiye\'de çok sayıda endemik türle temsil edilir; mavi çiçekli tarla türü peygamber çiçeği olarak bilinir.'),
  ('Güzelavratotu (Atropa belladonna) adını, eskiden kadınların gözbebeklerini büyütmek için kullanmasından alır. Bu etkiye yol açan maddeler hangi familyanın tipik bileşenleridir?', 'Patlıcangillerin alkaloitleri', ['Gülgillerin şekerleri', 'Buğdaygillerin nişastaları', 'Turpgillerin kükürtlü yağları ve asitleri'], 'Güzelavratotu patlıcangillerdendir ve atropin gibi tropan alkaloitleri içerir; atropin göz muayenesinde gözbebeğini büyütmek için kullanılmıştır.'),
  ('Aşılamanın başarılı olması için aşı kalemi ile anacın hangi dokularının birbirine denk getirilmesi en önemlidir?', 'Kambiyum katmanlarının', ['Öz dokularının', 'Kütikula katmanlarının', 'Kök tüylerinin ve epidermisin'], 'Kaynaşmayı yeni hücre üreten kambiyum sağlar; kalemle anacın kambiyumları temas etmezse iletim bağlantısı kurulamaz.'),
  ('Venüs sinek kapanının kapanını kapatması için tetik kıllarına belirli bir süre içinde genellikle iki kez dokunulması gerekir. Bu özelliğin bitkiye yararı nedir?', 'Yağmur damlası gibi cansız uyarılarda boşa kapanmayı önler', ['Böceğin kaçmasını kolaylaştırır', 'Kapanın daha yavaş kapanmasını sağlar', 'Bitkinin çiçeklerinin daha çok tozlaşmasını ve tohum vermesini sağlar'], 'Kapanış ve sindirim çok enerji ister. İki dokunuş şartı, rastgele çarpan bir nesne yerine hareket eden bir avın yakalanma olasılığını artırır.'),
  ('Yaprakları üzerindeki yapışkan sıvı damlacıklı tüylerle küçük böcekleri yakalayan ve Türkiye\'nin bazı turbalıklarında da doğal olarak bulunan böcekçil bitki cinsi hangisidir?', 'Drosera (güneş gülü)', ['Nepenthes (testi bitkisi)', 'Dionaea (Venüs sinek kapanı)', 'Sarracenia (borazan bitkisi)'], 'Drosera yapraklarındaki parlak salgı damlaları böcekleri yapıştırır, tüyler ve yaprak kıvrılarak avı sindirir. Türkiye\'de Karadeniz turbalıklarında görülür.'),
  ('Su içinde yaşayan ve küçük keseciklerinin kapağını açıp suyu emerek minik canlıları yakalayan böcekçil bitki hangisidir?', 'Kabarcık otu (Utricularia)', ['Güneş gülü (Drosera)', 'Testi bitkisi (Nepenthes)', 'Küstüm otu (Mimosa pudica) ve akrabaları'], 'Utricularia\'nın kesecikleri içerdeki basınç düşüklüğü sayesinde tetiklendiğinde suyu ve avı bir anda içeri çeker; bilinen en hızlı bitki hareketlerindendir.'),
  ('Ökse otunun beyaz meyvelerindeki yapışkan madde, tohumlarının yayılmasında nasıl bir rol oynar?', 'Kuşların gagasına ve dışkısına yapışan tohum dallara tutunur', ['Tohumu rüzgârda uçuracak kanat oluşturur', 'Tohumu su üzerinde yüzdürür', 'Tohumu toprağa doğru iterek derine gömülmesini sağlar'], 'Ökse otu meyvelerini yiyen kuşlar yapışkan tohumları gagalarını dallara sürterek ya da dışkıyla bırakır; tohum doğrudan konak dalına yapışarak çimlenir.'),
  ('Epifit orkidelerin hava köklerinin dışını saran süngerimsi, ölü hücrelerden oluşan tabakanın işlevi nedir?', 'Yağmur suyunu ve nemi hızla emmek', ['Böcekleri yakalamak', 'Konak ağacın özsuyunu emmek', 'Tozlaşma için gece boyunca güçlü koku salmak'], 'Velamen adı verilen bu tabaka sünger gibi suyu hızla emer ve köklerin kurumasını önler.'),
  ('Bazı kurak bölge bitkilerinde stomaların yaprak yüzeyindeki çukurlar içine gömülü olması ve tüylerle çevrilmesi neyi sağlar?', 'Stoma çevresinde nemli bir hava tabakası tutulmasını', ['Yaprağın daha fazla ışık soğurmasını', 'Stomaların sürekli açık kalmasını', 'Böceklerin stomalara girip içerde yumurtlamasını'], 'Çukur içindeki ve tüyler arasındaki durgun hava nemli kalır; dış hava ile nem farkı azaldığı için terleme yavaşlar.'),
  ('Namib Çölü\'nde yaşayan, ömrü boyunca yalnızca iki yaprak geliştiren ve bu yaprakları sürekli tabandan uzayan, yüzlerce yıl yaşayabilen bitki hangisidir?', 'Welwitschia mirabilis', ['Rafflesia arnoldii', 'Adansonia digitata', 'Dionaea muscipula ve akrabaları'], 'Welwitschia açık tohumlu bir bitkidir; iki şerit yaprağı tabandan büyümeye devam eder ve uçlarda rüzgârla parçalanır.'),
  ('Göknar ile ladin ağaçlarını kozalakları üzerinden ayırt etmek isteyen bir ormancı hangi özelliğe bakmalıdır?', 'Göknarda kozalak dik durur, ladinde aşağı sarkar', ['Göknarda kozalak kırmızı, ladinde mavidir', 'Göknarın kozalağı yoktur, ladininki vardır', 'İkisinde de kozalak toprak altında gelişir ve görülmez'], 'Göknar kozalakları dalda dik durur ve olgunlaşınca dal üzerinde pul pul dağılır; ladin kozalakları aşağı sarkar ve bütün hâlinde düşer.'),
  ('Bir dal üzerinde iğne yapraklar teker teker dizilmiş; iğneler yassı, alt yüzünde iki beyaz şerit var ve koparılınca dalda yuvarlak, düz bir iz kalıyor. Bu dal en büyük olasılıkla hangi ağaca aittir?', 'Göknar', ['Ladin', 'Çam', 'Ardıç ya da servi'], 'Göknar iğneleri yassıdır ve vantuz gibi düz bir izle dala bağlanır; ladin iğneleri dört köşelidir ve küçük çıkıntılar üzerinde durur. Çamlarda iğneler demet hâlindedir.'),
  ('Meme ve yumurtalık kanserlerinin tedavisinde kullanılan paklitaksel (taksol) adlı ilaç ilk olarak hangi bitki grubundan elde edilmiştir?', 'Porsuk ağaçlarından', ['Çam ağaçlarından', 'Söğüt ağaçlarından', 'Kınakına ağaçlarından'], 'Paklitaksel ilk kez Pasifik porsuğunun (Taxus brevifolia) kabuğundan izole edilmiştir; bugün porsuk yapraklarından yarı sentezle üretilir.'),
  ('Kaliforniya\'daki Beyaz Dağlar\'da yaşayan ve bazı bireylerinin 4000 yılı aştığı halka sayımıyla belirlenen, klonal olmayan en yaşlı ağaçlar arasında sayılan tür hangisidir?', 'Kıl kozalaklı çam (Pinus longaeva)', ['Kıyı sekoyası (Sequoia sempervirens)', 'Anadolu çınarı (Platanus orientalis)', 'Afrika baobabı (Adansonia digitata)'], 'Pinus longaeva kurak ve soğuk dağ koşullarında çok yavaş büyür; yıllık halkaları dendrokronoloji çalışmalarında da kullanılmıştır.'),
  ('Akdeniz kıyılarında kızılçama benzeyen ama daha ince iğneli olan ve Türkiye\'de doğal yayılışı oldukça sınırlı kalan çam türü hangisidir?', 'Halep çamı', ['Sarıçam', 'Karaçam', 'Kıl kozalaklı çam'], 'Halep çamı (Pinus halepensis) Batı ve Orta Akdeniz\'de yaygındır; Türkiye\'de doğal olarak yalnızca küçük alanlarda, örneğin Adana ve Muğla çevresinde görülür.'),
  ('Bir kozalaklı ormanında toprak genellikle asidiktir ve yere düşen iğneler yavaş ayrışır. Bunun başlıca nedeni nedir?', 'İğnelerin reçineli ve mumlu olup zor çürümesi', ['İğnelerin içinin azotla dolu olması', 'Ağaçların yere sürekli tuz salgılaması', 'Kökler tarafından düşen iğnelerin hemen yeniden emilmesi'], 'Kalın kütikula, reçine ve fenolik bileşikler iğnelerin ayrışmasını yavaşlatır; ayrışırken açığa çıkan asitler de toprağı asitleştirir.'),
  ('Türkiye\'de ormanlar, yükseltiye göre farklı ağaç türlerinin kuşaklar hâlinde yayıldığı bir dizilim gösterir. Bu açıdan Toroslar\'ın güney yamacında denizden yukarıya doğru tipik dizilim hangisidir?', 'Maki, kızılçam, karaçam ve sedir-göknar', ['Sedir, maki, kızılçam ve karaçam', 'Karaçam, maki, sedir ve kızılçam', 'Göknar, kızılçam, maki ve karaçam'], 'Kıyıda sıcaklık ve kuraklık maki ile kızılçamı öne çıkarır; yükseldikçe serinleyen dağlarda karaçam, daha yukarıda sedir ve Toros göknarı yer alır.'),
  ('Meşe dallarında bazı arıcık türlerinin yumurta bırakmasıyla oluşan ve tanen bakımından zengin olduğu için eskiden mürekkep ve boya yapımında kullanılan yuvarlak urlara ne ad verilir?', 'Mazı', ['Palamut', 'Reçine', 'Kozalak'], 'Mazılar bitkinin böceğe tepki olarak oluşturduğu urlardır (gal); yüksek tanen içerikleri nedeniyle demirle karıştırılarak mürekkep yapılmıştır.'),
  ('Şişe mantarının su geçirmez olması, hücre duvarlarında biriken hangi maddeden kaynaklanır?', 'Süberin', ['Selüloz', 'Nişasta', 'Klorofil'], 'Mantar hücrelerinin duvarları mumsu süberinle kaplıdır; bu madde suyu ve gazları geçirmez.'),
  ('Kızılağaç (Alnus) ağaçlarının fakir ve ıslak topraklarda hızla büyüyebilmesinin önemli bir nedeni nedir?', 'Köklerindeki ortak canlılarla azot bağlamaları', ['Yapraklarıyla böcek yakalamaları', 'Gövdelerinde su depolamaları', 'Kozalaklarının yangından sonra açılıp tohum dökmesi'], 'Kızılağaç köklerinde Frankia adlı bakterilerle ortak yaşar; bu bakteriler havadaki azotu bağlar ve ağaç baklagiller gibi toprağı zenginleştirir.'),
  ('Parklarda sık rastlanan at kestanesi ile yenilebilir kestane arasındaki ilişki için hangisi doğrudur?', 'Yakın akraba değildir; at kestanesi tohumları yenmez', ['İkisi aynı türün farklı çeşitleridir', 'At kestanesi tohumları daha tatlıdır', 'İkisi de meşe familyasındandır ve tohumları yenir'], 'At kestanesi (Aesculus) sabun ağacıgillere aittir ve tohumları saponinler nedeniyle zehirlidir; yenilen kestane ise kayıngillerdendir.'),
  ('Ceviz ağacının altında başka bitkilerin zor yetişmesi, köklerinden ve yapraklarından toprağa geçen hangi tür olayla açıklanır?', 'Allelopati', ['Fototropizma', 'Simbiyoz', 'Partenokarpi'], 'Ceviz juglon adlı bir madde salgılar; bu madde birçok bitkinin çimlenme ve büyümesini engeller. Bitkilerin kimyasallarla birbirini etkilemesine allelopati denir.'),
  ('Keçiboynuzu ağacının tohumları için yaygın olarak anlatılan ve kuyumculukta kullanılan bir ağırlık biriminin adına kaynaklık ettiği düşünülen özellik nedir?', 'Tohum ağırlıklarının birbirine yakın olduğu düşüncesi', ['Tohumlarının altın renginde olması', 'Tohumlarının suda çözünmesi', 'Tohumlarının ışık saçması'], 'Karat sözcüğünün keçiboynuzunun Yunanca adından geldiği kabul edilir; tohumların birbirine benzer ağırlıkta olduğu düşünüldüğünden tartı birimi olarak kullanılmıştır.'),
  ('Hollanda karaağaç hastalığı adıyla bilinen ve 20. yüzyılda Avrupa\'da milyonlarca karaağacın ölümüne yol açan etken hangisidir?', 'Kabuk böcekleriyle taşınan bir mantar', ['Kökleri kemiren bir kemirgen', 'Yaprakları yiyen bir kuş türü', 'Toprağa karışan tuz ve kimyasal atıklar'], 'Hastalık ksilemi tıkayan bir mantardan (Ophiostoma) kaynaklanır ve ağaçtan ağaca kabuk böcekleriyle taşınır.'),
  ('Gürgen ile kayın ağaçlarının ikisi de düz gri kabuklu olabilir. Meyvelerine bakarak bunları ayırmak isteyen biri neyi görürse gürgen olduğuna karar verir?', 'Üç parçalı yaprakçık benzeri kanatlara bağlı küçük fındıkçıklar', ['Dikenli bir kabuk içinde üçgen tohumlar', 'Kadeh biçimli bir tabana oturmuş palamutlar', 'Dik duran odunsu kozalaklar'], 'Gürgen (Carpinus) meyveleri üç loblu kanatlı bir brakteye bağlı küçük fındıkçıklardır; kayının meyveleri ise dikenli bir kabuk içindeki üçgen kayın tohumlarıdır.'),
  ('Davis ve Hedge\'in tanımladığı, Gümüşhane-Erzincan yöresinden Toroslar\'a, İskenderun Körfezi\'ne doğru uzanan ve iki yanındaki floraların belirgin biçimde farklılaştığı floristik sınır hangi adla bilinir?', 'Anadolu Çaprazı', ['Kuzey Anadolu Fayı', 'Wallace Çizgisi', 'Bereketli Hilal'], 'Anadolu Çaprazı (Anatolian Diagonal) boyunca pek çok tür yayılışını sona erdirir; doğusu ile batısı arasındaki floristik farklılık endemizmi de artırır.'),
  ('Türkiye\'nin bitkilerinin tanımlandığı, ilk cildi 1965\'te yayımlanan ve uzun yıllar boyunca Peter H. Davis\'in editörlüğünde hazırlanan temel eser hangisidir?', 'Flora of Turkey and the East Aegean Islands', ['Species Plantarum', 'De Materia Medica', 'Historia Plantarum'], 'Davis\'in yönettiği on ciltlik bu eser, ek ciltleriyle birlikte Türkiye florasının bilimsel temelini oluşturur.'),
  ('Türkiye\'de en çok türle temsil edilen bitki cinsi olarak bilinen ve bozkırlarda dikenli yastık biçimli çalılarıyla görülen cins hangisidir?', 'Geven (Astragalus)', ['Sığırkuyruğu (Verbascum)', 'Adaçayı (Salvia)', 'Peygamber çiçeği (Centaurea)'], 'Astragalus baklagillerdendir ve Türkiye\'de yüzlerce türü bulunur; dikenli gevenler İç ve Doğu Anadolu bozkırlarının tipik bitkileridir.'),
  ('Uzun çiçek başaklı, genellikle sarı çiçekli ve tüylü yapraklı olan; Türkiye\'de türlerinin büyük çoğunluğu endemik olduğundan ülkemizin bu cinsin önemli bir çeşitlilik merkezi sayıldığı bitki hangisidir?', 'Sığırkuyruğu (Verbascum)', ['Lale (Tulipa)', 'Kardelen (Galanthus)', 'Ardıç (Juniperus) ve servi (Cupressus)'], 'Türkiye\'de sığırkuyruğu cinsinin iki yüzü aşkın türü bulunur ve bunların büyük bir kısmı endemiktir.'),
  ('Bazı bitkiler yalnızca jips ya da serpantin gibi sıra dışı kimyasal yapıdaki topraklarda yetişir ve bu yüzden dar alanlarda endemik kalır. Bu tür endemizme ne ad verilir?', 'Edafik endemizm', ['Kozmopolitlik', 'İklimsel göç', 'Kültür endemizmi'], 'Edafik etkenler toprakla ilgilidir. Özel toprak koşullarına uyum sağlayan türler başka topraklarda rekabet edemez ve o toprağa bağımlı kalır.'),
  ('Bir öğrenci \'Endemik türler her zaman nadirdir\' diyor. Bu ifade için en doğru değerlendirme hangisidir?', 'Her zaman doğru değildir; endemik bir tür kendi bölgesinde bol olabilir', ['Kesinlikle doğrudur; endemik türler hep birkaç bireyden oluşur', 'Doğrudur; çünkü endemik türler yalnızca adalarda yaşar', 'Yanlıştır; çünkü endemik türler tüm kıtalarda bulunur'], 'Endemizm yayılış alanıyla ilgilidir, birey sayısıyla değil. Örneğin bir ülkeye endemik bir ağaç o ülkede geniş ormanlar oluşturabilir.'),
  ('Ankara\'nın Gölbaşı ilçesindeki Mogan Gölü çevresine özgü olan ve çiçekleri ışık altında farklı renklerde görünmesiyle \'yanardöner\' adıyla bilinen endemik bitki hangisidir?', 'Centaurea tchihatcheffii', ['Crocus ancyrensis', 'Tulipa gesneriana', 'Galanthus nivalis subsp. imperati'], 'Yanardöner peygamber çiçeği tek yıllık bir bitkidir; dünyada yalnızca Gölbaşı çevresinde yetişir ve yaşam alanının daralması nedeniyle tehlike altındadır.'),
  ('Endemik bir bitkinin tohumlarının gen bankasında saklanması önemli bir önlemdir. Ancak bu yöntemin tek başına yeterli olmamasının en önemli nedeni nedir?', 'Tür doğal ortamındaki ilişkilerinden ve evriminden kopar', ['Tohumlar gen bankasında hemen çimlenir', 'Gen bankaları yalnızca hayvanları saklar', 'Tohumların saklanması türü kozmopolit yapar'], 'Tohum bankası türün genetik malzemesini saklar ama tozlaştırıcılar, toprak ortakları ve değişen iklime uyum gibi doğadaki süreçler ancak yerinde korumayla sürer.'),
  ('Sıtmaya karşı kullanılan artemisinin, geleneksel Çin tıbbında da yer alan hangi bitkiden elde edilir?', 'Tatlı pelin (Artemisia annua)', ['Sarı kantaron (Hypericum perforatum)', 'Yüksük otu (Digitalis purpurea)', 'Ada çayı (Salvia officinalis)'], 'Artemisininin keşfi Çinli bilim insanı Tu Youyou\'ya 2015 Nobel Fizyoloji veya Tıp Ödülü\'nü kazandırmıştır.'),
  ('İzmir kekiği olarak bilinen Origanum onites\'in kendine özgü keskin kokusunu veren ve antiseptik etkili uçucu yağ bileşeni hangisidir?', 'Karvakrol', ['Kafein', 'Nikotin', 'Kapsaisin ya da piperin'], 'Kekik yağının ana bileşenlerinden karvakrol ve timol, bitkiye kokusunu ve mikrop öldürücü özelliğini verir.'),
  ('Meyankökü bitkisinin kökü şeker katılmadan da çok tatlıdır. Bu tatlılığı sağlayan madde hangisidir?', 'Glisirizin', ['Sakaroz', 'Kinin', 'Tanen ve reçine asitleri'], 'Meyankökü (Glycyrrhiza glabra) köklerindeki glisirizin şekerden kat kat tatlıdır; şekerleme ve şerbet yapımında kullanılır.'),
  ('Keten bitkisinden hem kumaş yapımında kullanılan lif hem de yağ elde edilir. Keten lifi bitkinin hangi kısmından gelir?', 'Gövdesindeki sağlam lif demetlerinden', ['Tohum tüylerinden', 'Çiçek yapraklarından', 'Kök tüylerinden ve kök kabuğundan'], 'Keten lifleri gövdenin floem kısmında bulunan uzun sklerenkima liflerinden elde edilir; tohumlarından ise beziryağı çıkarılır.'),
  ('Genetik çalışmalar, en eski kültür buğdaylarından siyez (Triticum monococcum) buğdayının Türkiye\'de hangi dağın çevresindeki yabani atalarından evcilleştirildiğini göstermiştir?', 'Karacadağ', ['Ağrı Dağı', 'Uludağ', 'Erciyes Dağı'], '1997\'de yayımlanan bir genetik çalışma, kültür siyezinin Diyarbakır-Şanlıurfa arasındaki Karacadağ\'da yetişen yabani siyez topluluklarına en yakın olduğunu göstermiştir.'),
  ('Mısırın evcilleştirildiği yabani ata bitkinin adı nedir ve bu süreç nerede gerçekleşmiştir?', 'Teosinte; Meksika', ['Siyez; Anadolu', 'Kınoa; Peru', 'Sorgum; Etiyopya'], 'Mısır, Meksika\'nın güneyinde yabani bir ot olan teosinteden binlerce yıllık seçilimle geliştirilmiştir.'),
  ('Rus bilim insanı Nikolay Vavilov kültür bitkileri hakkında hangi önemli kavramı ortaya koymuştur?', 'Kültür bitkilerinin köken ve çeşitlilik merkezleri', ['Kalıtımın bezelyedeki temel yasaları', 'Bitkilerin ikili adlandırma sistemi', 'Fotosentezde oksijenin kaynağı'], 'Vavilov kültür bitkilerinin yabani akrabalarının en çeşitli olduğu bölgeleri tespit ederek gen merkezleri kavramını geliştirmiş; Anadolu\'yu da bu merkezler arasında saymıştır.'),
  ('Charles Darwin\'in bitkilerle ilgili çalışmaları arasında orkidelerin tozlaşmasını incelemesi hangi fikrine destek olmuştur?', 'Çiçek yapısı ile tozlaştırıcıların birlikte evrimleşmesi', ['Bitkilerin bilinçli olarak böcek seçmesi', 'Türlerin hiçbir zaman değişmemesi', 'Orkidelerin sporla çoğalması'], 'Darwin, Madagaskar\'da çok uzun nektar mahmuzlu bir orkideyi tozlaştıracak uzun hortumlu bir gece kelebeğinin bulunması gerektiğini öngörmüş; bu kelebek sonradan keşfedilmiştir.'),
  ('Toros Dağları\'nda orman üst sınırının Kuzey Anadolu dağlarına göre genellikle daha yüksekte bulunması en çok hangi etkenle açıklanır?', 'Güneyde olduğu için sıcaklığın daha yüksek olması', ['Toroslar\'ın daha alçak olması', 'Torosların hiç yağış almaması', 'Toroslar\'da yalnızca geniş yapraklıların bulunması'], 'Daha güneyde ve güneşe dönük konumdaki dağlarda aynı yükseltide sıcaklık daha yüksektir; bu nedenle ağaçlar daha yukarılara çıkabilir.'),
  ('Bir bitkinin fotosentezle ürettiği oksijen miktarı, aynı anda solunumda tükettiği oksijen miktarına eşit olduğunda ışık şiddeti hangi noktadadır?', 'Işık dengelenme (kompanzasyon) noktasında', ['Işık doyma noktasında', 'Tamamen karanlıkta', 'Donma ve kaynama noktaları arasında'], 'Işık dengelenme (kompanzasyon) noktasında fotosentez ve solunum hızları eşittir; bitki net olarak ne oksijen verir ne de alır.'),
  ('Bir çiçek, erkek organları olgunlaşıp polen saçtıktan bir süre sonra dişi organını olgunlaştırıyor. Bu zaman farkı bitkiye hangi yararı sağlar?', 'Kendi kendini döllemeyi azaltıp çapraz tozlaşmayı artırır', ['Polenlerin daha ağır olmasını sağlar', 'Çiçeğin hiç böcek çekmemesini sağlar', 'Meyvenin tohumsuz olmasını sağlar'], 'Erkek ve dişi organların farklı zamanda olgunlaşması aynı çiçeğin kendi poleniyle döllenmesini zorlaştırır; böylece genetik çeşitlilik artar.'),
  ('Arpa tohumlarının ıslatılıp çimlendirilmesiyle hazırlanan malt, bira ve bazı gıdaların yapımında kullanılır. Çimlenme sırasında tohumda hangi önemli değişim gerçekleşir?', 'Nişasta enzimlerle şekerlere parçalanır', ['Nişasta proteine dönüşür', 'Tohumda klorofil depolanır', 'Tohum kabuğu selülozdan yağa dönüşür'], 'Çimlenen tohumda giberellin uyarısıyla amilaz enzimi salgılanır; endospermdeki nişasta maltoz gibi şekerlere parçalanır ve embriyonun kullanımına sunulur.'),
  ('İncirin içindeki yüzlerce küçük tanecik nedir?', 'İçe dönük çiçeklerden gelişen küçük meyveler', ['Ağacın polen taneleri', 'Meyvenin içinde biriken şeker kristalleri', 'Meyveyi yiyen böceklerin yumurtaları'], 'İncir aslında içi çiçeklerle kaplı, ağzı küçük bir delikle açılan bir çiçek durumudur (sikonyum); tanecikler bu çiçeklerin küçük meyveleridir.'),
  ('Bazı incir çeşitlerinde meyve bağlamak için ağaçlara yabani incir (ilek) dalları asılır. Bu geleneksel uygulamanın amacı nedir?', 'İncir arılarının polen taşımasını sağlamak', ['Ağacı soğuktan korumak', 'Meyvelere tat vermek', 'Ağaca gölge sağlamak'], 'Aydın yöresinde \'ilek asma\' denen bu uygulamada yabani incirden çıkan küçük incir arıları polenleri kültür inciri çiçeklerine taşır.'),
  ('Narın her bir tanesinin dışındaki sulu kırmızı kısım botanik açıdan nedir?', 'Etlenmiş tohum kabuğu', ['Ayrı bir meyve', 'Yaprak parçası', 'Polen kesesi'], 'Narın yenen sulu taneleri, tohumu saran etli dış tohum kabuğundan (sarkotesta) oluşur; içteki sert kısım tohumun kendisidir.'),
  ('Avokado ve hurma meyvelerinin iri, tek tohumlu olması tohum yayılımı açısından hangi tür hayvanlara uygun olabileceğini düşündürür?', 'Meyveyi bütün yiyebilen iri hayvanlara', ['Polen toplayan küçük arılara', 'Toprakta yaşayan solucanlara', 'Su altındaki balıklara'], 'İri tohumlu etli meyveler geçmişte de günümüzde de genellikle büyük memeliler ve iri kuşlar tarafından yenip taşınmaya uygundur.'),
  ('Dev sekoya ağaçları dünyadaki en büyük hacimli canlılar arasında sayılır. Bu ağaçların doğal yayılış alanı neresidir?', 'Kaliforniya\'daki Sierra Nevada dağlarının batı yamaçları', ['Sibirya\'nın kuzey kıyıları', 'Amazon Havzası\'nın merkezi', 'Avustralya\'nın iç çölleri'], 'Sequoiadendron giganteum yalnızca Sierra Nevada\'nın batı yamaçlarında küçük korular hâlinde doğal olarak yetişir.'),
  ('Endonezya\'da yetişen ve çiçeklendiğinde çürük et kokusu yaymasıyla bilinen titan arum (Amorphophallus titanum) için hangisi doğrudur?', 'Dünyanın en büyük dallanmamış çiçek durumlarından birini oluşturur', ['Tek hücreli bir alg türüdür', 'Böcek yakalayan bir sinek kapanıdır', 'Kozalaklı bir ağaçtır'], 'Titan arumun çiçek durumu üç metreyi aşabilir; kokusu leş sineklerini ve leş böceklerini tozlaşma için çeker.'),
  ('Geniş bir alana yayılmış, birbirine benzer görünen çok sayıda bitki gövdesi aslında toprak altındaki tek bir kök sisteminden çıkmış ve genetik olarak aynıysa, bu yapı için en uygun ifade hangisidir?', 'Tek bir klonal birey', ['Farklı türlerin karışımı', 'Birbirine yabancı tohumların fideleri', 'Rüzgârla gelen sporların ürünü'], 'Kavak gibi bazı bitkiler kök sürgünleriyle çoğalıp geniş alanlara yayılan, genetik olarak özdeş klonlar oluşturur; görünüşte orman olsa da tek bir bireydir.'),
  ('Kaktüs ile Afrika\'daki bazı sütleğen türleri birbirine çok benzer görünür: etli gövde, diken ve az yaprak. Ancak farklı familyalardandır. Bu benzerlik en iyi nasıl açıklanır?', 'Benzer kurak koşullara bağımsız olarak uyum sağlamaları', ['İkisinin aynı türün çeşitleri olması', 'İkisinin de insanlar tarafından üretilmesi', 'Birinin diğerinin tohumundan türemesi'], 'Benzer çevre koşulları farklı soylarda benzer yapıların ortaya çıkmasına yol açabilir; buna yakınsak (konverjan) evrim denir.'),
  ('Gül dallarındaki dikenler ile kaktüs dikenleri arasındaki köken farkı için hangisi doğrudur?', 'Kaktüs dikenleri yaprak, gül dikenleri kabuk kökenlidir', ['İkisi de değişmiş köklerdir', 'İkisi de değişmiş çiçeklerdir', 'Gül dikenleri yaprak, kaktüs dikenleri kök kökenlidir'], 'Kaktüslerde dikenler değişmiş yapraklardır; güldeki \'dikenler\' ise kabuk dokusundan gelişen çıkıntılardır ve kolayca koparılabilir.'),
  ('Kireçli topraklarda yetiştirilen bazı bitkilerin genç yapraklarında damarlar yeşil kalırken damar araları sararıyor. Bu belirti en çok hangi elementin alınamamasıyla ilgilidir?', 'Demir', ['Karbon', 'Oksijen', 'Hidrojen'], 'Bazik ve kireçli topraklarda demir bitkinin alamayacağı biçimlere dönüşür; demir klorofil yapımı için gerekli olduğundan genç yapraklarda damar arası sararma görülür.'),
  ('Bir bitki türü aynı bölgede bulunan iki farklı topluluğundan birinde mor, diğerinde beyaz çiçekler açıyor ama başka bütün özellikleri aynı. Bir botanikçi bu iki topluluğu nasıl değerlendirmelidir?', 'Önce aralarında üreme ve genetik farklılık olup olmadığını araştırmalı', ['Yalnızca renge bakarak kesinlikle iki ayrı tür saymalı', 'Renk farkı nedeniyle birini yok etmeli', 'İkisini de başka bir ülkeye taşımalı'], 'Çiçek rengi tek başına tür ayırmak için yeterli olmayabilir; aynı türün renk varyetelerine sık rastlanır. Karar morfolojik, genetik ve üreme verileriyle verilir.'),
  ('Portakal ve limonun içindeki sulu dilimler, meyve kabuğunun iç yüzeyinden gelişen ve özsuyla dolan çok sayıda tüysü keseden oluşur. Bu yapıdaki meyve tipine ne ad verilir?', 'Hesperidyum', ['Bakla', 'Kapsül', 'Aken'], 'Hesperidyum turunçgillere özgü, kalın kabuklu bir üzümsü meyve tipidir; dış kabukta kokulu yağ bezleri bulunur.'),
];
